export function premiumProductBySlug(slug: string) { return premiumProducts.find((product) => product.slug === slug); }
export function premiumProductsForCategory(slug?: string) { if (!slug || slug === "all") return premiumProducts; return premiumProducts.filter((product) => product.categorySlug === slug); }
export function premiumRelatedProducts(product: PremiumProduct) { return premiumProducts.filter((item) => item.id !== product.id && item.productType === product.productType).slice(0, 3); }

